import { describe, expect, it } from "vitest";

import { privateTaskLink, tokenFromHash } from "../private_link";

describe("privateTaskLink", () => {
  it("points to the task page of this webapp", () => {
    const link = privateTaskLink("my task", "a-token");

    expect(link.origin).toBe(window.location.origin);
    expect(link.pathname).toBe("/my%20task");
  });

  it("carries the token in the fragment, which tokenFromHash reads back", () => {
    // base64url, as generated by the server
    const token = "Ab-_0123456789";

    const link = privateTaskLink("task", token);

    expect(link.search).toBe("");
    expect(tokenFromHash(link.hash)).toBe(token);
  });
});

describe("tokenFromHash", () => {
  it("finds no token in other fragments", () => {
    expect(tokenFromHash("")).toBeUndefined();
    expect(tokenFromHash("#section")).toBeUndefined();
  });
});
